/* ==============================================================
   Rainmaker X · app · products
   RX Funds, SPVs, fund detail, Alternatives (options, forwards, DP interest, Liquid Security,
   special terms, own contract) and the Representatives page.
   ============================================================== */
'use strict';

// RX Funds page: RX50 index plus managed funds with a filter bar.
function viewFunds(main) {
  const fq = fundsF.q.toLowerCase(); const keep = f => (fundsF.status === 'all' || f.status === fundsF.status) && (!fq || f.name.toLowerCase().includes(fq) || (f.strategy || '').toLowerCase().includes(fq));
  const fundsOnly = D.FUNDS.filter(f => f.type === 'fund' && keep(f)); const rx50 = D.FUNDS.find(f => f.type === 'index'); const rxCh = D.change(rx50, '1D');
  main.innerHTML = `<div class="page wide">
    ${pageHead({ icon: PH.funds, title: 'RX Funds', sub: 'Rainmaker-managed vehicles built from exchange order flow, plus the RX50 index that tracks the most liquid names on the platform. Fund interests are available to verified investors and can themselves be listed on the exchange. Single-company vehicles live under <a class="link" href="#/spvs">SPVs</a>.', actions: `<a class="btn outline sm" href="#/spvs">Rainmaker SPVs</a><a class="btn sm" href="#/representatives">Talk to a fund representative</a>`, stats: [['RX50 index', rx50.nav.toFixed(2), `<span class="${cls(rxCh)}">${pct(rxCh)}</span> today`], ['Managed funds', fundsOnly.length, `${fundsOnly.filter(f => f.status === 'Open').length} open for subscriptions`], ['Assets under management', compact(fundsOnly.reduce((s_, f) => s_ + f.aum, 0)), 'across managed funds'], ['Lowest minimum', money(Math.min(...fundsOnly.map(f => f.min)), 0), 'per subscription']] })}
    ${filterBar('funds-filter', [['all', 'All'], ['Open', 'Open'], ['Waitlist', 'Waitlist'], ['Closed', 'Closed']], fundsF.status, fundsF.q, 'Search funds or strategy')}
    ${(() => { const grp = (title, sub, list, extra) => list.length ? `<div class="between" style="margin:${title === 'Index' ? 0 : 26}px 0 12px"><div><h2 style="font-size:20px">${title}</h2><div class="muted small">${sub}</div></div>${extra || ''}</div><div class="fund-grid">${list.map(fundCard).join('')}</div>` : ''; return grp('Index', 'The RX50, generated from platform order flow', D.FUNDS.filter(f => f.type === 'index')) + grp('Managed funds', 'Diversified and thematic vehicles built from exchange order flow', fundsOnly); })()}
    <div class="card xlink" style="margin-top:26px"><div class="card-body between" style="flex-wrap:wrap;gap:12px"><div><b>Rainmaker SPVs</b><div class="small muted">Single-company vehicles that hold a block bought through the exchange or the desk. ${D.FUNDS.filter(f => f.type === 'spv' && f.status !== 'Closed').length} open now.</div></div><span class="row"><a class="btn outline custom sm" href="#/new/arrange/spv">Form a new SPV</a></span></div></div></div>`;
  wireFilter(main, 'funds-filter', fundsF, () => viewFunds(main));
}
// ---------------- SPVs ----------------
function viewSPVs(main) {
  const sq = spvF.q.toLowerCase(); const secOf = f => { const c = f.companyId ? D.company(f.companyId) : (f.basket && f.basket[0] ? D.company(f.basket[0].companyId) : null); return c ? c.sector : ''; };
  const sectors = Array.from(new Set(D.FUNDS.filter(f => f.type === 'spv').map(secOf).filter(Boolean))).sort();
  const spvs = D.FUNDS.filter(f => f.type === 'spv' && (spvF.status === 'all' || (spvF.status === 'Open' ? f.status !== 'Closed' : f.status === spvF.status)) && (spvF.sector === 'all' || secOf(f) === spvF.sector) && (!sq || f.name.toLowerCase().includes(sq) || secOf(f).toLowerCase().includes(sq)));
  const open = spvs.filter(f => f.status !== 'Closed'), closed = spvs.filter(f => f.status === 'Closed');
  main.innerHTML = `<div class="page wide">
    ${pageHead({ icon: PH.spvs, title: 'Rainmaker SPVs', sub: 'Single-company special purpose vehicles that hold a block bought through the exchange or the desk. Units give you the economics of the block without appearing on the company\'s cap table. Diversified vehicles and the RX50 live under <a class="link" href="#/funds">Funds</a>.', actions: `<a class="btn outline custom sm" href="#/new/arrange/spv">Form a new SPV</a><a class="btn sm" href="#/representatives">Talk to a representative</a>`, stats: [['Open vehicles', open.length, `${closed.length} fully subscribed`], ['Capacity remaining', compact(open.reduce((s_, f) => s_ + Math.max(0, f.capacity - f.aum), 0)), 'across open vehicles'], ['Committed', compact(spvs.reduce((s_, f) => s_ + f.aum, 0)), 'all Rainmaker SPVs'], ['Economics', '1% + 10%', 'management fee + carry']] })}
    ${filterBar('spv-filter', [['all', 'All'], ['Open', 'Open'], ['Closing', 'Closing'], ['Closed', 'Fully subscribed']], spvF.status, spvF.q, 'Search company or sector', `<select class="mini" data-fs><option value="all" ${spvF.sector === 'all' ? 'selected' : ''}>All sectors</option>${sectors.map(x => `<option ${spvF.sector === x ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select>`)}
    <div class="between" style="margin:0 0 12px"><div><h2 style="font-size:20px">Open and closing</h2><div class="muted small">Request units directly. Unverified members submit a request that their representative works.</div></div></div>
    <div class="fund-grid">${open.map(fundCard).join('') || '<div class="card empty">No vehicles are open right now.</div>'}</div>
    ${closed.length ? `<div class="between" style="margin:26px 0 12px"><div><h2 style="font-size:20px">Fully subscribed</h2><div class="muted small">Closed vehicles. Units may be listed on the exchange as a fund interest.</div></div></div><div class="fund-grid">${closed.map(fundCard).join('')}</div>` : ''}
    <div class="card" style="margin-top:26px"><div class="card-head"><span class="label">How a Rainmaker SPV works</span></div><div class="card-body"><div class="term-list" style="grid-template-columns:repeat(4,1fr)">${[['1 · Block sourced', 'The desk negotiates a block from an employee, early investor or fund on the exchange.'], ['2 · Vehicle forms', 'Rainmaker forms a Delaware LLC that buys the block. Investors subscribe for units at the entry price.'], ['3 · Holds', 'The SPV holds until an IPO, acquisition or block sale. Units can be listed on the exchange meanwhile.'], ['4 · Distributes', 'Proceeds distribute to unit holders after the 1% management fee and 10% carry.']].map(t => `<div class="term"><div class="k">${t[0]}</div><div class="v">${t[1]}</div></div>`).join('')}</div></div></div></div>`;
  wireFilter(main, 'spv-filter', spvF, () => viewSPVs(main));
}
// ---------------- Alternatives: options, forwards, DP interest, Liquid Security, special terms ----------------
const ALT_ICON = {
  options: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17l6-6 4 4 8-8"/><path d="M14 7h7v7"/></svg>',
  forwards: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg>',
  dp: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12A9 9 0 1 1 12 3v9z"/><path d="M21 8a9 9 0 0 0-6-4.5V8z"/></svg>',
  liquid: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3s6 6.5 6 11a6 6 0 0 1-12 0c0-4.5 6-11 6-11z"/></svg>',
  structured: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="#fff"/><circle cx="15" cy="12" r="2" fill="#fff"/><circle cx="7" cy="18" r="2" fill="#fff"/></svg>',
  own: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>',
};
// The Alternatives product menu: options, forwards, DP interest, Liquid Security, special terms, own contract.
const ALT_PRODUCTS = {
  options: { t: 'Options', s: 'Calls and puts on private shares', who: 'Hedge a position or take leveraged upside without buying the stock outright.', facts: [['Minimum', '$50,000 notional'], ['Tenor', '3 to 24 months'], ['Settlement', 'Physical or cash'], ['Counterparty', 'Desk or matched investor']], href: '#/new/arrange/option', cta: 'Request an option contract', hold: 'An option contract, not the shares', liq: 'Exercise, or sell the contract back to the desk', cp: 'Desk or matched investor', min: '$50,000', docs: 'Option agreement, transfer notice' },
  forwards: { t: 'Forwards', s: 'Agree a price now, settle later', who: 'Lock in a price today for shares that transfer on a date or on a liquidity event.', facts: [['Minimum', '$100,000 notional'], ['Deposit', 'Typically 20%'], ['Settles', 'On a date or an event'], ['Counterparty', 'Desk or matched investor']], href: '#/new/arrange/forward', cta: 'Request a forward', hold: 'A contract to buy or sell at a fixed price', liq: 'Settles on the date or event', cp: 'Desk or matched investor', min: '$100,000', docs: 'Forward agreement, deposit escrow' },
  dp: { t: 'DP interest', s: 'A slice of one desk deal', tag: 'New', who: 'Participate in a single block the desk is buying, with no shares to hold and no vehicle to form.', facts: [['Ticket', 'From $25,000'], ['Fee', '1% of the block'], ['Term', 'Until the block exits'], ['Reporting', 'Quarterly + K-1']], cta: 'Request a DP interest', hold: 'Participation in one block', liq: 'Until the block exits; interests are listable', cp: 'Rainmaker', min: '$25,000', docs: 'Participation agreement, K-1' },
  liquid: { t: 'Liquid Security', s: 'Private exposure with a standing exit', tag: 'Rainmaker', who: 'Own the upside of a private company and sell back to Rainmaker in monthly windows, at a published price.', facts: [['Minimum', '$10,000'], ['Standing bid', 'RX price less 2.5%'], ['Windows', 'Monthly, T+2 cash'], ['Fee', '0.75% per year']], cta: 'Request Liquid Security units', hold: 'Rainmaker-issued units on one company', liq: 'Monthly windows, cash in two days', cp: 'Rainmaker standing bid', min: '$10,000', docs: 'Unit subscription' },
  structured: { t: 'Special terms', s: 'Collars, tranches, financing, swaps', who: 'A bid or ask with conditions the standard book cannot express: round-linked pricing, collars, contingencies, tranches, seller financing, share swaps.', facts: [['Minimum', 'None'], ['Pricing', 'Fixed, discount to round, or collar'], ['Delivery', 'One go or in tranches'], ['Counterparty', 'Any verified investor']], href: '#/new/arrange/structured', cta: 'Build a special-terms order', hold: 'Shares, on your conditions', liq: 'Goes on the book once agreed', cp: 'Any verified investor', min: 'None', docs: 'Standard transfer documents plus a rider' },
  own: { t: 'Your own contract', s: 'Propose any instrument and terms', who: 'Write the contract you want. Describe the instrument, the economics and your clauses; the desk reviews it, prices it and comes back with a term sheet.', facts: [['Instrument', 'Anything you can describe'], ['Terms', 'Set by you'], ['Review', 'Desk + compliance'], ['Reply', 'Term sheet in Requests']], cta: 'Propose a contract', hold: 'Whatever you propose', liq: 'As set in your terms', cp: 'Desk decides', min: 'Set by you', docs: 'Drafted by the desk from your proposal' },
};
// Clause chips for the Your own contract builder.
const OWN_CLAUSES = ['ROFR waiver required', 'Price collar', 'Delivery in tranches', 'Seller financing', 'Information rights', 'Most-favoured-nation pricing', 'Early termination right', 'Collateral posted by counterparty', 'Confidentiality', 'Governing law: Delaware'];
// Alternatives: product tiles, product hero, steps, and the request form for each product.
function viewAlternatives(main, product) {
  if (!ALT_PRODUCTS[product]) product = 'options';
  const P = ALT_PRODUCTS[product];
  const liq = c => D.liveListings(c.id).length + D.liveBids(c.id).length;
  const sorted = D.COMPANIES.slice().sort((a, b) => liq(b) - liq(a)); const top = sorted.slice(0, 6);
  const elig = D.COMPANIES.filter(c => c.liquid).slice().sort((a, b) => liq(b) - liq(a)); const spread = RX_CONFIG.products.liquidSecuritySpread;
  const deals = top.map(c => { const asks = D.liveListings(c.id).slice().sort((a, b) => b.qty - a.qty); return asks[0] ? { c, big: asks[0] } : null; }).filter(Boolean).slice(0, 5);
  const mine = D.arrangements().filter(a => ['dp', 'liquid', 'own', 'option', 'forward', 'structured'].includes(a.type));
  const stat = { options: `${top.length} names priced`, forwards: `${top.length} names priced`, dp: `${deals.length} blocks working`, liquid: `${elig.length} eligible names`, structured: '6 term types', own: mine.filter(a => a.type === 'own').length ? `${mine.filter(a => a.type === 'own').length} proposed` : 'Any instrument' };
  const tag = m => m.tag ? `<span class="badge gold alt-tag">${m.tag}</span>` : '';
  const ALT_CAT = { options: 'derivatives', forwards: 'derivatives', dp: 'rainmaker', liquid: 'rainmaker', structured: 'bespoke', own: 'bespoke' };
  const menu = `<div class="chips alt-filter" style="margin-bottom:12px">${[['all', 'All products'], ['derivatives', 'Derivatives'], ['rainmaker', 'Rainmaker products'], ['bespoke', 'Bespoke terms']].map(([k, l]) => `<button class="chip ${altF === k ? 'on' : ''}" data-altf="${k}" type="button">${l}</button>`).join('')}</div><div class="alt-menu">${Object.entries(ALT_PRODUCTS).filter(([k]) => altF === 'all' || ALT_CAT[k] === altF).map(([k, m]) => `<a class="alt-tile ${k === product ? 'on' : ''}" href="#/alternatives/${k}"><span class="alt-ico">${ALT_ICON[k]}</span><b>${m.t}${tag(m)}</b><span class="s">${m.s}</span><span class="stat">${stat[k]}</span></a>`).join('')}</div>`;
  const cta = P.href ? `<a class="btn" href="${P.href}">${P.cta}</a>` : `<button class="btn" type="button" data-alt-focus>${P.cta}</button>`;
  const hero = `<div class="card alt-hero"><div class="alt-hero-main"><span class="alt-ico lg">${ALT_ICON[product]}</span><div><div class="row" style="gap:10px"><h2>${P.t}</h2>${tag(P)}</div><p class="muted">${P.who}</p><div class="alt-facts">${P.facts.map(f => `<span class="fact"><span class="k">${f[0]}</span>${f[1]}</span>`).join('')}</div></div></div><div class="alt-hero-cta">${cta}<a class="btn outline" href="#/representatives">Talk to a representative</a></div></div>`;
  const gate = D.isVisitor() ? `<div class="callout"><a class="link" href="#/signin">Sign in</a> or <a class="link" href="#/join">create an account</a> to request any of these products.</div>` : D.canTrade() ? '' : gateCard('this request');
  const how = (title, rows, foot) => `<div class="card"><div class="card-head"><span class="label">${title}</span></div><div class="card-body alt-how">${rows.map((t, i) => `<div class="alt-step"><span class="n">${i + 1}</span><div><b>${t[0]}</b><div class="muted small">${t[1]}</div></div></div>`).join('')}</div>${foot ? `<div class="card-foot form-foot" style="background:#fff">${foot}</div>` : ''}</div>`;
  const sel = (name, val, extra) => `<select name="${name}">${extra || ''}${D.COMPANIES.slice().sort((a, b) => a.name.localeCompare(b.name)).map(c => `<option value="${c.id}" ${c.id === val ? 'selected' : ''}>${esc(c.name)} · ${money(D.price(c.id))}</option>`).join('')}</select>`;
  const draft = `<div class="callout tiny">Draft product terms for the prototype. Final terms are subject to Rainmaker's product and legal review.</div>`;
  let body = '';
  if (product === 'options') {
    body = `<div class="two-col"><div class="stack">
      <div class="card"><div class="card-head"><span class="label">Indicative 12-month at-the-money premiums</span><span class="small muted">Black-Scholes · 55% vol · 4% rate</span></div><table class="table compact"><thead><tr><th>Company</th><th class="num">RX price</th><th class="num">Call</th><th class="num">Put</th><th></th></tr></thead><tbody>${top.map(c => { const S = D.price(c.id); const call = D.optionPrice({ S, K: S, T: 1, sigma: 0.55, type: 'call' }), put = D.optionPrice({ S, K: S, T: 1, sigma: 0.55, type: 'put' }); return `<tr class="clickable" data-href="#/new/arrange/option/${c.id}"><td><span class="row">${logo(c, 'sm')}<b>${esc(c.name)}</b></span></td><td class="num strong">${money(S)}</td><td class="num">${money(call)} <span class="tiny muted">${pct(call / S)}</span></td><td class="num">${money(put)} <span class="tiny muted">${pct(put / S)}</span></td><td class="num"><a class="btn outline custom sm" href="#/new/arrange/option/${c.id}">Request</a></td></tr>`; }).join('')}</tbody></table><div class="card-foot small muted">Indicative only. The desk prices each contract on the actual strike, tenor, collateral and transfer restrictions.</div></div>
    </div><div class="stack">${gate}${how('How an option works here', [['Choose the contract', 'Call or put, American or European, strike and tenor, on one company\'s shares.'], ['Desk prices it', 'The desk quotes a premium; writers post collateral, typically 25% of notional.'], ['Term sheet', 'Accept the term sheet under Requests and the option agreement is signed.'], ['Exercise or expire', 'Settle physically (shares transfer, subject to ROFR) or in cash against the RX price.']], `<a class="btn outline custom" href="#/new/arrange/option">Request an option contract</a>`)}</div></div>`;
  } else if (product === 'forwards') {
    body = `<div class="two-col"><div class="stack">
      <div class="card"><div class="card-head"><span class="label">Indicative forward prices</span><span class="small muted">RX price + 4% carry per year + 1.5% desk spread</span></div><table class="table compact"><thead><tr><th>Company</th><th class="num">RX price</th><th class="num">6-month</th><th class="num">12-month</th><th class="num">24-month</th><th></th></tr></thead><tbody>${top.map(c => { const S = D.price(c.id); const f = T => S * (1 + 0.04 * T) * 1.015; return `<tr class="clickable" data-href="#/new/arrange/forward/${c.id}"><td><span class="row">${logo(c, 'sm')}<b>${esc(c.name)}</b></span></td><td class="num strong">${money(S)}</td><td class="num">${money(f(.5))}</td><td class="num">${money(f(1))}</td><td class="num">${money(f(2))}</td><td class="num"><a class="btn outline custom sm" href="#/new/arrange/forward/${c.id}">Request</a></td></tr>`; }).join('')}</tbody></table><div class="card-foot small muted">Indicative only. Forwards can also settle on a liquidity event (IPO or acquisition) instead of a date.</div></div>
    </div><div class="stack">${gate}${how('How a forward works here', [['Fix the price', 'Agree a purchase or sale price now for settlement on a date or on a liquidity event.'], ['Deposit', 'Buyers post a deposit, typically 20%, into escrow. The balance is due at settlement.'], ['Term sheet', 'The desk structures every forward and returns a term sheet under Requests.'], ['Settle', 'Shares transfer at the fixed price. If ROFR is exercised, the deposit is refunded or the forward converts to cash, as chosen.']], `<a class="btn outline custom" href="#/new/arrange/forward">Request a forward</a>`)}</div></div>`;
  } else if (product === 'dp') {
    body = `<div class="two-col"><div class="stack">
      <div class="card"><div class="card-head"><span class="label">Blocks the desk is working</span><span class="small muted">Largest live asks on the book</span></div><table class="table compact"><thead><tr><th>Company</th><th class="num">Block</th><th class="num">Ask</th><th class="num">Block value</th><th></th></tr></thead><tbody>${deals.map(d => `<tr><td><span class="row">${logo(d.c, 'sm')}<b>${esc(d.c.name)}</b></span></td><td class="num">${num(d.big.qty)} sh</td><td class="num strong">${money(d.big.price)}</td><td class="num">${compact(d.big.qty * d.big.price)}</td><td class="num"><button class="btn outline custom sm" data-alt-pick="${d.c.id}">Participate</button></td></tr>`).join('') || '<tr><td colspan="5" class="muted small">No blocks on the book right now.</td></tr>'}</tbody></table></div>
      ${how('How a DP interest works', [['Desk sources a block', 'The desk negotiates a block in one company from an employee, early investor or fund.'], ['You take a slice', 'A deal participation interest gives you a pro-rata share of that single block for a fixed ticket.'], ['Rainmaker holds', 'No shares in your name, no cap-table entry, no vehicle to form. Rainmaker holds the block.'], ['Proceeds pass through', 'On IPO, acquisition or block sale the proceeds distribute net of a 1% fee.']])}${draft}
    </div><div class="stack">${gate}
      <form class="card" id="alt-form" data-type="dp"><div class="card-head"><h2 style="font-size:20px">Request a DP interest</h2></div><div class="card-body stack"><div class="field"><label>Deal (company)</label>${sel('companyId', top[0].id)}</div><div class="field"><label>Ticket (USD)</label><input name="amount" type="number" min="25000" step="5000" value="50000" required></div><div class="field"><label>Note to the desk (optional)</label><textarea name="note" rows="2" placeholder="Preferred entry, timing, or an existing block you know of"></textarea></div><label class="check"><input type="checkbox" name="ack" required><span>I understand this is an indication of interest in a desk-structured product, not a binding commitment.</span></label></div><div class="card-foot form-foot" style="background:#fff"><button class="btn" type="submit" ${D.isVisitor() ? 'disabled' : ''}>Send to the desk</button></div></form></div></div>`;
  } else if (product === 'liquid') {
    const nextWin = new Date(); nextWin.setMonth(nextWin.getMonth() + 1, 1);
    body = `<div class="two-col"><div class="stack">
      <div class="card"><div class="card-head"><span class="label">Liquid prices today</span><span class="small muted">Next window ${fmtDate(nextWin.getTime())}</span></div><table class="table compact"><thead><tr><th>Company</th><th class="num">RX price</th><th class="num">Standing bid</th><th class="num">Units</th><th></th></tr></thead><tbody>${elig.map(c => { const S = D.price(c.id); const inv = D.liveListings(c.id).length; return `<tr><td><span class="row">${logo(c, 'sm')}<b>${esc(c.name)}</b></span></td><td class="num strong">${money(S)}</td><td class="num">${money(S * (1 - spread))}</td><td class="num">${inv ? '<span class="badge verified">Available</span>' : '<span class="badge status">Waitlist</span>'}</td><td class="num"><button class="btn outline custom sm" data-alt-pick="${c.id}">Request</button></td></tr>`; }).join('')}</tbody></table></div>
      ${how('How a Liquid Security works', [['Rainmaker wraps the shares', 'Units are issued against shares Rainmaker holds in one company, so you get the upside like a shareholder.'], ['Published price', `Every day Rainmaker publishes a liquid price: the RX price less a ${(spread * 100).toFixed(1)}% liquidity spread.`], ['Standing bid', 'Rainmaker buys units back at that price in monthly windows. No counterparty search, no ROFR wait.'], ['Cash in two days', 'Sales settle T+2 in cash to your brokerage account.']])}${draft}
    </div><div class="stack">${gate}
      <form class="card" id="alt-form" data-type="liquid"><div class="card-head"><h2 style="font-size:20px">Request Liquid Security units</h2></div><div class="card-body stack"><div class="field"><label>Company</label>${sel('companyId', elig[0].id)}</div><div class="side-toggle"><button type="button" class="bid on" data-side="buy">Buy units</button><button type="button" class="ask" data-side="sell">Sell units</button></div><input type="hidden" name="side" value="buy"><div class="field"><label>Amount (USD)</label><input name="amount" type="number" min="10000" step="1000" value="25000" required></div><div class="field"><label>Note to the desk (optional)</label><textarea name="note" rows="2" placeholder="Timing, or shares you would like wrapped"></textarea></div><label class="check"><input type="checkbox" name="ack" required><span>I understand this is an indication of interest, not a binding commitment.</span></label></div><div class="card-foot form-foot" style="background:#fff"><button class="btn" type="submit" ${D.isVisitor() ? 'disabled' : ''}>Send to the desk</button></div></form></div></div>`;
  } else if (product === 'own') {
    const proposals = mine.filter(a => a.type === 'own');
    body = `<div class="two-col"><div class="stack">
      <form class="card" id="alt-form" data-type="own"><div class="card-head"><h2 style="font-size:20px">Propose your own contract</h2><span class="small muted">Everything here is optional except a name and a company</span></div><div class="card-body stack">
        <div class="grid-2"><div class="field"><label>What do you call it?</label><input name="name" required placeholder="e.g. Revenue-linked note, put spread, structured block" maxlength="80"></div><div class="field"><label>Underlying company</label>${sel('companyId', top[0].id, '<option value="">Not tied to one company</option>')}</div></div>
        <div class="grid-2"><div class="field"><label>You want to</label><select name="side"><option value="buy">Buy / receive exposure</option><option value="sell">Sell / give exposure</option><option value="either">Either, depending on price</option></select></div><div class="field"><label>Size (USD notional)</label><input name="amount" type="number" min="1000" step="1000" value="250000" required></div></div>
        <div class="grid-2"><div class="field"><label>Price basis</label><select name="basis"><option value="fixed">Fixed price</option><option value="rx">Relative to the RX price</option><option value="round">Discount to the next priced round</option><option value="409a">Relative to the latest 409A</option><option value="other">Something else (describe below)</option></select></div><div class="field"><label>Price or level</label><input name="price" placeholder="e.g. $62.00, RX −10%, 25% discount"></div></div>
        <div class="grid-2"><div class="field"><label>Term (months)</label><input name="months" type="number" min="1" max="120" value="12"></div><div class="field"><label>Settles on</label><select name="trigger"><option value="date">A fixed date</option><option value="ipo">IPO</option><option value="acq">Acquisition</option><option value="any">Any liquidity event</option><option value="demand">On demand, either side</option></select></div></div>
        <div class="grid-2"><div class="field"><label>Settlement</label><select name="settle"><option value="physical">Physical (shares transfer)</option><option value="cash">Cash</option><option value="either">Either</option></select></div><div class="field"><label>Preferred counterparty</label><select name="cp"><option value="desk">Rainmaker desk</option><option value="investor">Another verified investor</option><option value="either">Either</option></select></div></div>
        <div class="field"><label>Your clauses</label><div class="chips" id="own-chips">${OWN_CLAUSES.map(c => `<button type="button" class="chip" data-clause="${esc(c)}">${esc(c)}</button>`).join('')}</div><textarea name="clauses" rows="5" placeholder="One term per line. Click a chip to add it, then edit freely."></textarea></div>
        <div class="grid-2"><div class="field"><label>Attach a term sheet or draft (optional)</label><input name="file" type="file" accept=".pdf,.doc,.docx,.txt"></div><div class="field"><label>Or paste key terms</label><textarea name="paste" rows="2" placeholder="Paste from your own document"></textarea></div></div>
        <div class="field"><label>Note to the desk (optional)</label><textarea name="note" rows="2" placeholder="Why this structure, and anything the desk should know"></textarea></div>
        <label class="check"><input type="checkbox" name="ack" required><span>I understand this is a proposal for the desk to review, not an order or a binding commitment, and that the desk may decline or counter.</span></label>
      </div><div class="card-foot form-foot" style="background:#fff"><button class="btn" type="submit" ${D.isVisitor() ? 'disabled' : ''}>Send proposal to the desk</button><span class="small muted">Comes back as a term sheet under Requests</span></div></form>
      ${proposals.length ? `<div class="card"><div class="card-head"><span class="label">Your proposals</span><span class="small muted">${proposals.length}</span></div>${arrangementsTable(proposals, false)}</div>` : ''}
    </div><div class="stack">${gate}
      <div class="card"><div class="card-head"><span class="label">Term sheet preview</span><span class="small muted">Updates as you type</span></div><div class="card-body"><div class="ts-preview" id="own-preview"></div></div></div>
      ${how('What happens next', [['Desk review', 'A representative and the desk read your proposal within one business day.'], ['Compliance check', 'Compliance confirms the instrument can be offered to you and papered.'], ['Term sheet', 'The desk prices it and returns a term sheet, or counters, under Requests.'], ['Paperwork', 'Once agreed, the desk drafts the agreement and it moves through the settlement tracker.']])}</div></div>`;
  } else {
    body = `<div class="two-col"><div class="stack">${how('Terms the desk can structure', [['Round-linked pricing', 'Price set as a discount to the next priced round or the latest 409A.'], ['Collars', 'A floor and a cap on the price between now and settlement.'], ['Contingencies', 'ROFR waiver, IPO by a date, or a minimum round valuation.'], ['Tranches', 'Buy or sell in several tranches over months.'], ['Seller financing', 'A down payment now and the balance over time.'], ['Share swaps', 'Exchange shares in one company for shares in another, with a cash true-up.']])}</div><div class="stack">${gate}${how('How it works', [['Custom order', 'Special terms are a tile inside the Custom order flow.'], ['Desk pipeline', 'Your request is structured by your primary representative and the desk and comes back as a term sheet under Requests.'], ['Book', 'Once agreed it goes on the book or settles directly, like any other order.']], `<a class="btn outline custom" href="#/new/arrange/structured">Build a special-terms bid or ask</a>`)}</div></div>`;
  }
  const compare = '';
  const openArr = mine.filter(a => ['submitted', 'structuring', 'term sheet'].includes(a.status));
  main.innerHTML = `<div class="page wide">${pageHead({ icon: PH.alts, title: 'Alternatives', actions: `<a class="btn outline sm" href="#/new/custom">Custom order flow</a><a class="btn sm" href="#/alternatives/own">Propose your own contract</a>`, stats: [['Products', Object.keys(ALT_PRODUCTS).length, 'plus anything you propose'], ['Names priced today', top.length, 'options and forwards'], ['Your open requests', openArr.length, openArr.length ? `${openArr.filter(a => a.status === 'term sheet').length} term sheets to review` : 'nothing waiting on you'], ['Desk turnaround', '1 business day', 'to a term sheet or a counter']] })}
    ${menu}${hero}${body}${compare}</div>`;
  main.querySelectorAll('[data-altf]').forEach(b => b.onclick = () => { altF = b.dataset.altf; viewAlternatives(main, product); });
  const f = main.querySelector('#alt-form');
  main.querySelectorAll('[data-alt-pick]').forEach(b => b.onclick = () => { if (!f) return; f.companyId.value = b.dataset.altPick; f.scrollIntoView({ behavior: 'smooth', block: 'start' }); f.amount.focus(); });
  main.querySelectorAll('[data-alt-focus]').forEach(b => b.onclick = () => { if (!f) return; f.scrollIntoView({ behavior: 'smooth', block: 'start' }); const first = f.querySelector('input:not([type=hidden]), select'); if (first) first.focus(); });
  main.querySelectorAll('.side-toggle [data-side]').forEach(b => b.onclick = () => { main.querySelectorAll('.side-toggle button').forEach(x => x.classList.toggle('on', x === b)); f.side.value = b.dataset.side; });
  if (product === 'own' && f) {
    const TRIG = { date: 'a fixed date', ipo: 'an IPO', acq: 'an acquisition', any: 'any liquidity event', demand: 'demand, either side' }; const BASIS = { fixed: 'Fixed price', rx: 'Relative to RX price', round: 'Discount to next round', '409a': 'Relative to 409A', other: 'As described' };
    const preview = () => { const c = D.company(f.companyId.value); const lines = f.clauses.value.split(/\n+/).map(x => x.trim()).filter(Boolean); const file = f.file.files && f.file.files[0];
      main.querySelector('#own-preview').innerHTML = `<h4>${esc(f.name.value || 'Untitled instrument')}</h4><dl><dt>Underlying</dt><dd>${c ? `<span class="row" style="gap:6px">${logo(c, 'sm')}${esc(c.name)} · RX ${money(D.price(c.id))}</span>` : 'Not tied to one company'}</dd><dt>Direction</dt><dd>${f.side.value === 'buy' ? 'You buy / receive exposure' : f.side.value === 'sell' ? 'You sell / give exposure' : 'Either way, depending on price'}</dd><dt>Size</dt><dd>${money(+f.amount.value || 0, 0)} notional</dd><dt>Pricing</dt><dd>${BASIS[f.basis.value]}${f.price.value ? ` · ${esc(f.price.value)}` : ''}</dd><dt>Term</dt><dd>${f.months.value || '—'} months, settling on ${TRIG[f.trigger.value]}</dd><dt>Settlement</dt><dd>${f.settle.value === 'physical' ? 'Physical' : f.settle.value === 'cash' ? 'Cash' : 'Physical or cash'} · ${f.cp.value === 'desk' ? 'Rainmaker desk' : f.cp.value === 'investor' ? 'matched investor' : 'desk or matched investor'}</dd><dt>Clauses</dt><dd>${lines.length ? `<ul style="margin:0;padding-left:16px">${lines.map(l => `<li>${esc(l)}</li>`).join('')}</ul>` : '<span class="muted">None yet</span>'}</dd>${file ? `<dt>Attachment</dt><dd>${esc(file.name)}</dd>` : ''}${f.paste.value.trim() ? `<dt>Pasted terms</dt><dd class="small">${esc(f.paste.value.trim().slice(0, 240))}${f.paste.value.trim().length > 240 ? '…' : ''}</dd>` : ''}</dl><div class="tiny muted" style="margin-top:10px">Indicative summary of your proposal. The desk's term sheet is the only binding document.</div>`; };
    f.addEventListener('input', preview); f.addEventListener('change', preview); preview();
    main.querySelectorAll('[data-clause]').forEach(b => b.onclick = () => { const cur = f.clauses.value.trim(); if (cur.split(/\n/).includes(b.dataset.clause)) return; f.clauses.value = (cur ? cur + '\n' : '') + b.dataset.clause; b.classList.add('on'); preview(); });
  }
  if (f) f.addEventListener('submit', e => { e.preventDefault(); if (D.isVisitor()) { go('#/signin'); return; } const type = f.dataset.type; const c = f.companyId.value ? D.company(f.companyId.value) : null; const amt = +f.amount.value; const side = f.side ? f.side.value : 'buy';
    let what, extra = {};
    if (type === 'dp') what = `DP interest of ${money(amt, 0)} in the ${c.name} block`;
    else if (type === 'liquid') what = `${side === 'buy' ? 'Buy' : 'Sell'} ${money(amt, 0)} of ${c.name} Liquid Security units`;
    else { const file = f.file.files && f.file.files[0]; extra = { terms: { name: f.name.value.trim(), basis: f.basis.value, price: f.price.value.trim(), months: +f.months.value || null, trigger: f.trigger.value, settle: f.settle.value, cp: f.cp.value, clauses: f.clauses.value.split(/\n+/).map(x => x.trim()).filter(Boolean), paste: f.paste.value.trim(), attachment: file ? file.name : null } }; what = `${f.name.value.trim()} · ${side === 'buy' ? 'buy' : side === 'sell' ? 'sell' : 'either side'} ${money(amt, 0)}${c ? ' on ' + c.name : ''}${f.price.value.trim() ? ' @ ' + f.price.value.trim() : ''} · ${f.months.value || '?'}m`; }
    const a = D.submitArrangement(Object.assign({ type, companyId: c ? c.id : null, amount: amt, side, what, note: f.note.value.trim() }, extra)); toast(`${a.id} sent to the desk`); go('#/orders/arrangements'); });
}
// ---------------- staff access gate and not-found ----------------

// SPV units: "Buy from us" card when Rainmaker holds inventory, "Sell back to us" card when it provides liquidity (Ben, Oct 5 2026).
function spvBuyCard(f, off) {
  const bp = D.hasAccount() ? D.buyingPower() : 0;
  return `<form class="card" id="spv-buy"><div class="card-head"><h2 style="font-size:20px">Buy units from Rainmaker</h2><span class="badge gold">Rainmaker inventory</span></div><div class="card-body stack">${D.canTrade() ? '' : gateCard('buying units directly')}
    <div class="callout green">Rainmaker holds <b>${num(off.units)} units</b> of this vehicle for sale at unit value <b>${money(off.price)}</b> (${compact(off.units * off.price)}). Minimum ${money(f.min, 0)}, ${num(off.minUnits)} units. Buying opens a subscription: you sign the agreement, move the funds to escrow from your account, and Rainmaker issues the units.</div>
    <div class="field"><label>Units</label><input name="units" type="number" min="${off.minUnits}" max="${off.units}" step="1" value="${off.minUnits}" required></div>
    <table class="kv tight"><tr><th>Unit value</th><td>${money(off.price)}</td></tr><tr><th>Total</th><td id="spv-buy-total" class="strong">${money(off.minUnits * off.price, 0)}</td></tr>${D.canTrade() ? `<tr><th>Buying power</th><td>${money(bp, 0)}</td></tr>` : ''}<tr><th>Economics</th><td>${(f.fee * 100).toFixed(2)}% per year + ${Math.round((f.carry || 0) * 100)}% carry, inside the vehicle</td></tr>${off.held ? `<tr><th>You hold</th><td>${num(off.held)} units · avg ${money(off.holding.avgCost)}</td></tr>` : ''}</table>
    <label class="check"><input type="checkbox" name="ack" required><span>I have read the offering documents and understand units are illiquid except for any Rainmaker buy-back.</span></label>
  </div><div class="card-foot form-foot" style="background:#fff"><button class="btn bid" type="submit">${ICON.cart}<span class="bl">${D.canTrade() ? 'Buy from us' : 'Request to buy from us'}</span></button></div></form>`;
}
function spvSellCard(f, off) {
  const body = off.canSell
    ? `<div class="callout">Rainmaker provides liquidity in this vehicle: a standing bid of <b>${money(off.bid)}</b> per unit (unit value ${money(f.nav)} less ${(D.SPV_SPREAD * 100).toFixed(1)}%), cash in two business days.</div>
      ${off.held ? `<div class="field"><label>Units to sell (you hold ${num(off.held)})</label><input name="units" type="number" min="1" max="${off.held}" step="1" value="${off.held}" required></div>
      <table class="kv tight"><tr><th>Standing bid</th><td>${money(off.bid)}</td></tr><tr><th>You receive</th><td id="spv-sell-total" class="strong">${money(off.held * off.bid, 0)}</td></tr><tr><th>Your cost</th><td>${money(off.holding.avgCost)} per unit · ${money(off.holding.cost, 0)}</td></tr></table>` : `<div class="small muted">You hold no units of this vehicle yet. Units bought here can be sold back in this card.</div>`}`
    : `<div class="callout">Rainmaker is not providing liquidity in this vehicle right now. ${off.held ? `Your ${num(off.held)} units can be listed on the exchange: ask your primary representative.` : 'Units are held until the vehicle exits, or listed on the exchange through your primary representative.'}</div>`;
  const foot = off.canSell && off.held ? `<button class="btn ask" type="submit">${ICON.cash}<span class="bl">${D.canTrade() ? 'Sell back to us' : 'Request to sell back to us'}</span></button>` : !off.canSell && off.held ? `<a class="btn outline sm" href="#/messages">Ask my primary representative</a>` : '';
  return `<form class="card" id="spv-sell"><div class="card-head"><h2 style="font-size:20px">Sell back to Rainmaker</h2>${off.canSell ? '<span class="badge open">Standing bid</span>' : '<span class="badge status">No standing bid</span>'}</div><div class="card-body stack">${body}</div>${foot ? `<div class="card-foot form-foot" style="background:#fff">${foot}</div>` : ''}</form>`;
}

// Fund / SPV detail: chart, terms, allocation request.
function viewFund(main, id) {
  const f = D.fund(id); if (!f) { main.innerHTML = '<div class="page"><div class="card empty">Fund not found.</div></div>'; return; }
  if (f.type === 'index') return viewIndex(main);
  const rep_ = D.rep('rep-4'); const mine = D.allocations().filter(a => a.fundId === f.id); const off = f.type === 'spv' ? D.spvOffer(f) : null;
  main.innerHTML = `<div class="page wide"><div class="two-col">
    <div class="stack">
      <div class="card"><div class="company-head"><span class="fund-mark fund lg">RX</span><div style="flex:1"><h1 style="font-size:26px">${esc(f.name)}</h1><div class="row" style="margin-top:6px">${fundBadges(f)}<span class="muted small">${esc(f.strategy)}</span></div></div></div><div class="info-block"><p>${esc(f.desc)}</p></div></div>
      ${f.type === 'spv' ? (() => { const u = D.company(f.underlying); const rx = D.price(u.id); return `<div class="card"><div class="card-head"><span class="label">SPV terms</span><a class="link small" href="#/company/${u.id}">${esc(u.name)} company page</a></div><div class="card-body"><div class="term-list" style="grid-template-columns:repeat(3,1fr)"><div class="term"><div class="k">Underlying</div><div class="v">${esc(u.name)} ${esc(u.round.series)}</div></div><div class="term"><div class="k">Entry price</div><div class="v">${money(f.entryPrice)} · RX now ${money(rx)} (<span class="${cls((rx - f.entryPrice) / f.entryPrice)}">${pct((rx - f.entryPrice) / f.entryPrice)}</span>)</div></div><div class="term"><div class="k">Capacity</div><div class="v">${compact(f.aum)} of ${compact(f.capacity)} · ${Math.round(f.filled * 100)}% filled</div></div><div class="term"><div class="k">Economics</div><div class="v">${(f.fee * 100).toFixed(1)}% mgmt · ${(f.carry * 100).toFixed(0)}% carry</div></div><div class="term"><div class="k">${f.status === 'Closed' ? 'Closed' : 'Closes'}</div><div class="v">${fmtDate(f.closeDate)}</div></div><div class="term"><div class="k">Exit</div><div class="v">Distributes on IPO, acquisition or a block sale; units may be listed on the exchange</div></div></div><div class="alloc lg" style="margin-top:14px"><span style="width:${Math.round(f.filled * 100)}%;background:var(--teal)"></span></div><div class="small muted" style="margin-top:8px">Look-through: ${money(f.min, 0)} buys ≈ ${num(Math.round(f.min / rx))} underlying shares at today's RX price. Investors hold units in a Rainmaker-administered LLC; the SPV, not the investor, appears on the company's cap table.</div></div></div>`; })() : ''}
      <div class="card" id="fund-chart"><div class="card-head"><span class="label">${f.type === 'spv' ? 'Unit value (tracks the underlying RX price)' : 'Net asset value per unit'}</span><div class="seg"></div></div><div class="card-body"><div class="row" style="margin-bottom:12px"><span class="price-big" id="f-price">${money(f.nav)}</span><span class="chg" id="f-chg"></span></div><div class="chart-wrap"></div><div class="small muted" style="margin-top:10px">NAV is struck daily from RX prices of the underlying positions, net of the management fee. Sample data for prototyping only.</div></div></div>
      <div class="card"><div class="card-head"><span class="label">Holdings</span><span class="muted small">${f.basket.length} positions</span></div><table class="table compact"><thead><tr><th>Company</th><th class="num">Weight</th><th class="num">RX price</th><th class="num">3M change</th><th>Trend</th></tr></thead><tbody>${f.basket.slice().sort((a, b) => b.w - a.w).map(b => { const ch = D.change(b.c, '3M'); return `<tr class="clickable" data-href="#/company/${b.c.id}"><td><span class="row">${logo(b.c, 'sm')}<b>${esc(b.c.name)}</b></span></td><td class="num"><div class="row" style="justify-content:flex-end"><div class="alloc" style="max-width:90px"><span style="width:${(b.w * 100).toFixed(0)}%;background:var(--teal)"></span></div><span class="mono">${(b.w * 100).toFixed(1)}%</span></div></td><td class="num strong">${money(D.price(b.c.id))}</td><td class="num ${cls(ch)}">${pct(ch)}</td><td>${sparkline(D.series(b.c, '3M'), 64, 24)}</td></tr>`; }).join('')}</tbody></table></div>
    </div>
    <div class="stack">
      ${off && off.canBuy ? spvBuyCard(f, off) : `<form class="card" id="alloc-form"><div class="card-head"><h2 style="font-size:20px">${f.type === 'spv' ? 'Request SPV units' : 'Request an allocation'}</h2>${fundBadges(f)}</div><div class="card-body stack">${D.canTrade() ? '' : gateCard('this allocation')}
        ${f.status === 'Closed' ? `<div class="callout">This fund is fully deployed and closed to new capital. Secondary interests may be available on the exchange; ask your primary representative.</div>` : f.status === 'Waitlist' ? `<div class="callout">The current close is oversubscribed. Requests join the waitlist for the next close.</div>` : `<div class="callout green">Open for subscriptions. Minimum ${money(f.min, 0)}.</div>`}
        <div class="field"><label>Amount (USD)</label><input name="amount" type="number" min="${f.min}" step="1000" value="${f.min}" ${f.status === 'Closed' ? 'disabled' : ''} required></div>
        <table class="kv tight"><tr><th>Minimum</th><td>${money(f.min, 0)}</td></tr><tr><th>Fee</th><td>${(f.fee * 100).toFixed(2)}% per year</td></tr><tr><th>AUM</th><td>${compact(f.aum)}</td></tr><tr><th>Inception</th><td>${fmtDate(f.inception)}</td></tr><tr><th>Representative</th><td><a class="link" style="text-decoration:none" href="#/representatives">${esc(rep_.name)}</a></td></tr></table>
        <label class="check"><input type="checkbox" name="ack" required ${f.status === 'Closed' ? 'disabled' : ''}><span>I have read the offering documents and understand this is an indication of interest, not a binding commitment.</span></label>
      </div><div class="card-foot form-foot" style="background:#fff"><button class="btn" type="submit" ${f.status === 'Closed' ? 'disabled' : ''}>${f.status === 'Waitlist' ? 'Join waitlist' : f.type === 'spv' ? 'Request units' : 'Request allocation'}</button></div></form>`}
      ${off ? spvSubsCard(f) : ''}
      ${off ? spvSellCard(f, off) : ''}
      ${mine.length ? `<div class="card"><div class="card-head"><span class="label">Your requests</span></div><table class="table compact"><tbody>${mine.map(a => `<tr><td>${fmtPlaced(a.ts)}</td><td class="num strong">${money(a.amount, 0)}</td><td><span class="badge status">${esc(a.status)}</span></td></tr>`).join('')}</tbody></table></div>` : ''}
      <div class="card"><div class="card-head"><span class="label">Documents</span></div><div class="card-body stack" style="gap:10px">${['Private placement memorandum', 'Limited partnership agreement', 'Subscription agreement', 'Latest quarterly letter'].map(d => `<div class="between doc-row"><span class="row">${ICON.doc}${d}</span><button class="btn outline sm" data-doc="${d}">View</button></div>`).join('')}</div></div>
    </div></div></div>`;
  const card = main.querySelector('#fund-chart');
  mountPriceChart(card, f, { height: 300, periods: ['1D', '1M', '3M', '6M', '1Y', 'MAX'], initial: 'MAX', labelEl: card.querySelector('#f-price'), changeEl: card.querySelector('#f-chg') });
  const af = main.querySelector('#alloc-form'); if (af) af.addEventListener('submit', e => { e.preventDefault(); if (!D.canTrade()) { const rq = D.submitRequest({ kind: 'allocation', fundId: f.id, amount: +af.amount.value }); toast(`Request ${rq.id} sent to ${rep_.name}`); go('#/orders/requests'); return; } D.requestAllocation(f.id, +af.amount.value); toast('Allocation request sent to ' + rep_.name); render(); });
  // Buy from us / sell back to us: verified investors trade at once, unverified members send a request, visitors sign in.
  const spvForm = (sel, side) => { const fm = main.querySelector(sel); if (!fm) return; const totalEl = fm.querySelector(side === 'buy' ? '#spv-buy-total' : '#spv-sell-total'); const px = side === 'buy' ? off.price : off.bid;
    if (fm.units && totalEl) fm.units.addEventListener('input', () => { totalEl.textContent = money((+fm.units.value || 0) * px, 0); });
    fm.addEventListener('submit', e => { e.preventDefault(); if (D.isVisitor()) { go('#/signin'); return; } const u = Math.floor(+fm.units.value || 0);
      if (!D.canTrade()) { const rq = D.submitRequest({ kind: side === 'buy' ? 'spv-buy' : 'spv-sell', fundId: f.id, qty: u, price: px }); toast(`Request ${rq.id} sent to ${rep_.name}`); go('#/orders/requests'); return; }
      const r = side === 'buy' ? D.buySPV(f.id, u) : D.sellSPV(f.id, u); if (r.error) { toast(r.error, false); return; }
      toast(side === 'buy' ? `${r.sub.id} opened: ${num(r.units)} units reserved @ ${money(r.price)}. Sign the subscription agreement to continue.` : `Sold ${num(r.units)} units @ ${money(r.price)} back to Rainmaker`); render(); if (side === 'buy') { const el = document.querySelector('#spv-subs'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }); };
  if (off) { spvForm('#spv-buy', 'buy'); spvForm('#spv-sell', 'sell'); }
  main.querySelectorAll('[data-doc]').forEach(b => b.onclick = () => toast('Documents are placeholders in this prototype', false));
}

// ---------------- representatives ----------------
function viewReps(main) {
  const pr = D.profile();
  const myRep = D.rep(pr.rep); const offices = [...new Set(D.REPS.map(r => r.office))]; const pend = D.repRequestFor('you');
  main.innerHTML = `<div class="page wide">
    ${pageHead({ icon: PH.reps, title: 'Registered Representatives', sub: 'Every transaction on Rainmaker X is brokered by a FINRA-registered representative of Rainmaker Securities. Your primary representative confirms terms, coordinates company approvals and transfer paperwork, and settles the trade. CRD numbers link to BrokerCheck.', actions: `<a class="btn sm" href="#/messages">Message ${esc(myRep.name.split(' ')[0])}</a>`, stats: [['Your primary representative', esc(myRep.name), pend ? 'change requested: ' + esc(D.rep(pend.to).name) + ' to accept' : esc(myRep.title)], ['Representatives', D.REPS.length, 'FINRA-registered'], ['Offices', offices.length, esc(offices.join(' · '))], ['Coverage', 'Every sector on the exchange', 'plus funds and compliance']] })}
    <div class="company-grid">${D.REPS.map(r => `<div class="card card-body rep-card">
      <div class="row" style="gap:14px"><span class="avatar xl" style="background:${r.color}">${esc(r.name.split(' ').map(x => x[0]).join(''))}</span><div style="flex:1"><h3 style="font-size:18px">${esc(r.name)}</h3><div class="muted small">${esc(r.title)}</div></div>${pr.rep === r.id ? '<span class="badge verified">Primary</span>' : pend && pend.to === r.id ? '<span class="badge pending" title="Waiting for this representative to accept">Requested</span>' : ''}</div>
      <table class="kv tight"><tr><th>CRD #</th><td><a class="link" style="text-decoration:none" href="#/representatives">${esc(r.crd)}</a></td></tr><tr><th>Office</th><td>${esc(r.office)}</td></tr><tr><th>With Rainmaker</th><td>Since ${r.since}</td></tr><tr><th>Email</th><td>${esc(r.email)}</td></tr><tr><th>Phone</th><td>${esc(r.phone)}</td></tr></table>
      <div><div class="label dim" style="margin-bottom:6px">Licenses</div><div class="tags">${r.licenses.map(l => `<span class="tag">${esc(l)}</span>`).join('')}</div></div>
      <div><div class="label dim" style="margin-bottom:6px">Coverage</div><div class="tags">${r.sectors.map(l => `<span class="tag">${esc(l)}</span>`).join('')}</div></div>
      <div class="row" style="margin-top:auto"><button class="btn outline sm" data-intro="${r.id}">Request intro</button>${pr.rep === r.id ? '' : pend && pend.to === r.id ? '<span class="tiny muted">Awaiting their approval</span>' : `<button class="btn ghost sm" data-setrep="${r.id}">Make my primary representative</button>`}</div>
    </div>`).join('')}</div></div>`;
  main.querySelectorAll('[data-intro]').forEach(b => b.onclick = () => { const r = D.rep(b.dataset.intro); toast(`Intro request sent to ${r.name}`); });
  main.querySelectorAll('[data-setrep]').forEach(b => b.onclick = () => { const r = D.requestPrimaryRep('you', b.dataset.setrep); if (r.error) { toast(r.error, false); return; } toast(`${D.rep(b.dataset.setrep).name} has been asked to become your primary representative`); render(); });
}

